-- Disposable synthetic PostgreSQL fixture only; NEVER apply to a live service.
CREATE TABLE mt_users(id uuid primary key, employee_code text unique,name text, role text,active boolean,department text,job_title text,preferred_name text,phone text);
CREATE TABLE mt_leave_balances(user_id uuid primary key,days numeric);
CREATE TABLE mt_leave_requests(id uuid primary key,public_id text,requester_id uuid,type text,start_date date,end_date date,days numeric,status text,reason text,decided_at timestamptz,decided_by uuid,duration_kind text);
CREATE TABLE mt_leave_ledger(id uuid primary key,request_id uuid unique,user_id uuid,delta numeric,balance_after numeric,approved_by uuid,created_at timestamptz);
CREATE TABLE mt_leave_balance_adjustments(id uuid primary key,user_id uuid,delta_days numeric,balance_before numeric,balance_after numeric,reason text,approved_by uuid,created_at timestamptz);
CREATE TABLE mt_overtime_requests(id uuid primary key,public_id text,requester_id uuid,work_date date,start_time time,end_time time,minutes int,compensation_kind text,reason text,status text,decided_at timestamptz,decided_by uuid,work_kind text);
CREATE TABLE mt_substitute_time_ledger(id uuid primary key,user_id uuid,delta_minutes int,overtime_id uuid unique,leave_id uuid unique,approved_by uuid,created_at timestamptz);
CREATE TABLE mt_substitute_time_adjustments(id uuid primary key,user_id uuid,delta_minutes int,reason text,approved_by uuid,created_at timestamptz);
